        var centerX = lerp(_fromX, _toX, t);
        var centerY = lerp(_fromY, _toY, t);

        var nowDist = lerp(_fromDist, _toDist, curveT);

        var leftX = centerX - nowDist;
        var leftY = centerY;

        var rightX = centerX + nowDist;
