        let nodeData = _stickObj.nodes[i];
        _midLayer.strokeWeight(3);
        _midLayer.stroke(0, 0, 6);
        _midLayer.line(nodeData.x1, nodeData.y1, nodeData.x2, nodeData.y2);
        UpdateLayers();
        await sleep(1);
    }
}

